// InvoiceServiceHandler is an implementation of the hawkr.invoice.InvoiceService service.
type InvoiceServiceHandler interface {
	// 常用發票資料（B08）
	ListBuyerInvoiceProfiles(context.Context, *connect.Request[invoice.ListBuyerInvoiceProfilesRequest]) (*connect.Response[invoice.ListBuyerInvoiceProfilesResponse], error)
	CreateBuyerInvoiceProfile(context.Context, *connect.Request[invoice.CreateBuyerInvoiceProfileRequest]) (*connect.Response[invoice.BuyerInvoiceProfileResponse], error)
	UpdateBuyerInvoiceProfile(context.Context, *connect.Request[invoice.UpdateBuyerInvoiceProfileRequest]) (*connect.Response[invoice.BuyerInvoiceProfileResponse], error)
	DeleteBuyerInvoiceProfile(context.Context, *connect.Request[invoice.DeleteBuyerInvoiceProfileRequest]) (*connect.Response[invoice.DeleteBuyerInvoiceProfileResponse], error)
	SetDefaultBuyerInvoiceProfile(context.Context, *connect.Request[invoice.SetDefaultBuyerInvoiceProfileRequest]) (*connect.Response[invoice.BuyerInvoiceProfileResponse], error)
	// 訂單發票（B04/B05）
	GetOrderInvoice(context.Context, *connect.Request[invoice.GetOrderInvoiceRequest]) (*connect.Response[invoice.GetOrderInvoiceResponse], error)
	GetInvoiceDocument(context.Context, *connect.Request[invoice.GetInvoiceDocumentRequest]) (*connect.Response[invoice.GetInvoiceDocumentResponse], error)
	GetInvoiceDocumentFile(context.Context, *connect.Request[invoice.GetInvoiceDocumentFileRequest]) (*connect.Response[invoice.GetInvoiceDocumentFileResponse], error)
	// 買家發票中心（B09，端點 68–69）：跨訂單的文件列表 ＋ document-scoped 詳情。
	// 這兩支與上面 order-scoped 的 GetOrderInvoice／GetInvoiceDocument 並存而非取代：
	// §2.3 方向三（平台→買家）的發票不掛在任何訂單底下，order-scoped 的入口取不到它。
	// 授權述詞是 recipient_type='BUYER' AND recipient_ref_id=當前買家（58A B09「權限與邊界」）
	// ⇒ 只會回自己是買受人的文件，前端不得再自行過濾。
	ListBuyerInvoiceDocuments(context.Context, *connect.Request[invoice.ListBuyerInvoiceDocumentsRequest]) (*connect.Response[invoice.ListBuyerInvoiceDocumentsResponse], error)
	// 回既有的 GetInvoiceDocumentResponse（data 同為 InvoiceDocumentDetail）：符合 §6.2.2 決定 2
	// 的三個共用條件——payload 型別完全相同、語意是「同一份文件的另一種取得方式」、同屬買家角色面。
	GetBuyerInvoiceDocument(context.Context, *connect.Request[invoice.GetBuyerInvoiceDocumentRequest]) (*connect.Response[invoice.GetInvoiceDocumentResponse], error)
	// 付款後修改（B06）
	CreateInvoiceCorrection(context.Context, *connect.Request[invoice.CreateInvoiceCorrectionRequest]) (*connect.Response[invoice.InvoiceCorrectionResponse], error)
	GetInvoiceCorrection(context.Context, *connect.Request[invoice.GetInvoiceCorrectionRequest]) (*connect.Response[invoice.InvoiceCorrectionResponse], error)
	// 未收到發票申訴（B07）
	CreateInvoiceComplaint(context.Context, *connect.Request[invoice.CreateInvoiceComplaintRequest]) (*connect.Response[invoice.InvoiceComplaintResponse], error)
	ListOrderInvoiceComplaints(context.Context, *connect.Request[invoice.ListOrderInvoiceComplaintsRequest]) (*connect.Response[invoice.ListInvoiceComplaintsResponse], error)
	GetInvoiceComplaint(context.Context, *connect.Request[invoice.GetInvoiceComplaintRequest]) (*connect.Response[invoice.InvoiceComplaintResponse], error)
	// 買家在申訴流程中的三個動作（§7.3.5 K07／K11／K13）。三支都回**轉移後**的單筆，
	// 前端不必再打一次 GetInvoiceComplaint。K06 的主動半條（買家確認結案）Phase 1 不做，
	// 見 §6.1.6「為什麼是三支而不是四支」——不要看到 FSM 有四條就自己補第四支 RPC。
	RejectInvoiceComplaintResponse(context.Context, *connect.Request[invoice.RejectInvoiceComplaintResponseRequest]) (*connect.Response[invoice.InvoiceComplaintResponse], error)
	WithdrawInvoiceComplaint(context.Context, *connect.Request[invoice.WithdrawInvoiceComplaintRequest]) (*connect.Response[invoice.InvoiceComplaintResponse], error)
	ReopenInvoiceComplaint(context.Context, *connect.Request[invoice.ReopenInvoiceComplaintRequest]) (*connect.Response[invoice.InvoiceComplaintResponse], error)
	GetSellerInvoiceOverview(context.Context, *connect.Request[invoice.GetSellerInvoiceOverviewRequest]) (*connect.Response[invoice.GetSellerInvoiceOverviewResponse], error)
	// 稅務身分（S02）與自行開票責任條款（S04）
	GetSellerTaxProfile(context.Context, *connect.Request[invoice.GetSellerTaxProfileRequest]) (*connect.Response[invoice.SellerTaxProfileResponse], error)
	SaveSellerTaxProfileDraft(context.Context, *connect.Request[invoice.SaveSellerTaxProfileDraftRequest]) (*connect.Response[invoice.SellerTaxProfileResponse], error)
	SubmitSellerTaxProfile(context.Context, *connect.Request[invoice.SubmitSellerTaxProfileRequest]) (*connect.Response[invoice.SellerTaxProfileResponse], error)
	RequestSellerTaxExtension(context.Context, *connect.Request[invoice.RequestSellerTaxExtensionRequest]) (*connect.Response[invoice.SellerTaxProfileResponse], error)
	GetSelfIssueAttestation(context.Context, *connect.Request[invoice.GetSelfIssueAttestationRequest]) (*connect.Response[invoice.SelfIssueAttestationResponse], error)
	AcceptSelfIssueAttestation(context.Context, *connect.Request[invoice.AcceptSelfIssueAttestationRequest]) (*connect.Response[invoice.SelfIssueAttestationResponse], error)
	// AMEGO 憑證與啟用切點（S03）
	GetSellerProviderAccount(context.Context, *connect.Request[invoice.GetSellerProviderAccountRequest]) (*connect.Response[invoice.SellerProviderAccountResponse], error)
	PutSellerProviderCredentials(context.Context, *connect.Request[invoice.PutSellerProviderCredentialsRequest]) (*connect.Response[invoice.SellerProviderAccountResponse], error)
	VerifySellerProviderAccount(context.Context, *connect.Request[invoice.VerifySellerProviderAccountRequest]) (*connect.Response[invoice.SellerProviderAccountResponse], error)
	ActivateSellerProviderAccount(context.Context, *connect.Request[invoice.ActivateSellerProviderAccountRequest]) (*connect.Response[invoice.SellerProviderAccountResponse], error)
	RotateSellerProviderCredentials(context.Context, *connect.Request[invoice.RotateSellerProviderCredentialsRequest]) (*connect.Response[invoice.SellerProviderAccountResponse], error)
	// 免用統一發票與收據授權（S05）
	GetSellerReceiptAuthorization(context.Context, *connect.Request[invoice.GetSellerReceiptAuthorizationRequest]) (*connect.Response[invoice.SellerReceiptAuthorizationResponse], error)
	ConfirmSellerReceiptAuthorization(context.Context, *connect.Request[invoice.ConfirmSellerReceiptAuthorizationRequest]) (*connect.Response[invoice.SellerReceiptAuthorizationResponse], error)
	// 發票紀錄與異常（S06/S07/S08）
	ListSellerInvoiceDocuments(context.Context, *connect.Request[invoice.ListSellerInvoiceDocumentsRequest]) (*connect.Response[invoice.ListSellerInvoiceDocumentsResponse], error)
	GetSellerInvoiceDocument(context.Context, *connect.Request[invoice.GetSellerInvoiceDocumentRequest]) (*connect.Response[invoice.GetSellerInvoiceDocumentResponse], error)
	// S12 進項分頁（端點 72）：recipient-scoped，與上面 issuer-scoped 的銷項是兩個資料集。
	// 不能靠同一支 RPC 加 flag 分流——銷項可作廢可折讓、進項是唯讀報稅憑證，法律角色不同。
	// 停權賣家仍可讀（進項憑證是賣家的財產，與能否營業無關，58A S12「權限」）。
	ListSellerReceivedInvoiceDocuments(context.Context, *connect.Request[invoice.ListSellerReceivedInvoiceDocumentsRequest]) (*connect.Response[invoice.ListSellerReceivedInvoiceDocumentsResponse], error)
	ResendInvoiceNotification(context.Context, *connect.Request[invoice.ResendInvoiceNotificationRequest]) (*connect.Response[invoice.ResendInvoiceNotificationResponse], error)
	// 端點 71（買家 B05 重寄）。**與賣家版分成兩支是 §5.1 角色分離的硬要求**，
	//    不是重複：兩者的擁有者述詞不同（賣家用 store_id、買家用 buyer_id），
	//    而 §8.1.4 的 Tier A 要求「越權與不存在不可區分」＝ 擁有者必須進 WHERE。
	//    共用一支 request 的話 Gateway 送不出買家身分，服務端只剩兩條路：
	//    全部拒絕（端點死掉），或忽略擁有者（任何已登入買家可對任意 document_id
	//    觸發重寄 ＝ IDOR）。ADM 版早就分開了（ResendInvoiceNotificationForAdmin），
	//    買家版漏掉純粹是遺漏。
	//    Response 共用是允許的（§6.2.2 決定 2：payload 形狀完全相同）。
	ResendBuyerInvoiceNotification(context.Context, *connect.Request[invoice.ResendBuyerInvoiceNotificationRequest]) (*connect.Response[invoice.ResendInvoiceNotificationResponse], error)
	GetSellerInvoiceJob(context.Context, *connect.Request[invoice.GetSellerInvoiceJobRequest]) (*connect.Response[invoice.GetSellerInvoiceJobResponse], error)
	// 子路由 62R：端點 62 的前置讀取（order-scoped）。停權賣家唯一取得 job_id / version / can_report_external 的路徑
	ListOrderExternalIssuances(context.Context, *connect.Request[invoice.ListOrderExternalIssuancesRequest]) (*connect.Response[invoice.ListOrderExternalIssuancesResponse], error)
	// 端點 62：A4 受控人工出口的最後一步，RESOLVED_EXTERNALLY 的唯一入口（§7 J30）
	ReportExternalIssuance(context.Context, *connect.Request[invoice.ReportExternalIssuanceRequest]) (*connect.Response[invoice.GetSellerInvoiceJobResponse], error)
	// 買家申訴（S09/S10）
	ListSellerInvoiceComplaints(context.Context, *connect.Request[invoice.ListSellerInvoiceComplaintsRequest]) (*connect.Response[invoice.ListInvoiceComplaintsResponse], error)
	GetSellerInvoiceComplaint(context.Context, *connect.Request[invoice.GetSellerInvoiceComplaintRequest]) (*connect.Response[invoice.InvoiceComplaintResponse], error)
	RespondSellerInvoiceComplaint(context.Context, *connect.Request[invoice.RespondSellerInvoiceComplaintRequest]) (*connect.Response[invoice.InvoiceComplaintResponse], error)
	GetInvoiceOverviewForAdmin(context.Context, *connect.Request[invoice.GetInvoiceOverviewForAdminRequest]) (*connect.Response[invoice.GetInvoiceOverviewForAdminResponse], error)
	// 稅務身分審核（A02/A03）
	ListTaxReviewsForAdmin(context.Context, *connect.Request[invoice.ListTaxReviewsForAdminRequest]) (*connect.Response[invoice.ListTaxReviewsForAdminResponse], error)
	GetTaxReviewForAdmin(context.Context, *connect.Request[invoice.GetTaxReviewForAdminRequest]) (*connect.Response[invoice.GetTaxReviewForAdminResponse], error)
	DecideTaxReviewForAdmin(context.Context, *connect.Request[invoice.DecideTaxReviewForAdminRequest]) (*connect.Response[invoice.DecideTaxReviewForAdminResponse], error)
	DecideTaxExtensionForAdmin(context.Context, *connect.Request[invoice.DecideTaxExtensionForAdminRequest]) (*connect.Response[invoice.DecideTaxReviewForAdminResponse], error)
	// AMEGO 串接監控（A04/A09）
	ListProviderAccountsForAdmin(context.Context, *connect.Request[invoice.ListProviderAccountsForAdminRequest]) (*connect.Response[invoice.ListProviderAccountsForAdminResponse], error)
	GetProviderAccountForAdmin(context.Context, *connect.Request[invoice.GetProviderAccountForAdminRequest]) (*connect.Response[invoice.GetProviderAccountForAdminResponse], error)
	HealthCheckProviderAccountForAdmin(context.Context, *connect.Request[invoice.HealthCheckProviderAccountForAdminRequest]) (*connect.Response[invoice.GetProviderAccountForAdminResponse], error)
	DeactivateProviderAccountForAdmin(context.Context, *connect.Request[invoice.DeactivateProviderAccountForAdminRequest]) (*connect.Response[invoice.DeactivateProviderAccountForAdminResponse], error)
	ReactivateProviderAccountForAdmin(context.Context, *connect.Request[invoice.ReactivateProviderAccountForAdminRequest]) (*connect.Response[invoice.GetProviderAccountForAdminResponse], error)
	RevokeProviderAccountForAdmin(context.Context, *connect.Request[invoice.RevokeProviderAccountForAdminRequest]) (*connect.Response[invoice.RevokeProviderAccountForAdminResponse], error)
	ListProviderCutoversForAdmin(context.Context, *connect.Request[invoice.ListProviderCutoversForAdminRequest]) (*connect.Response[invoice.ListProviderCutoversForAdminResponse], error)
	// 發票與工作佇列（A05/A06）
	ListInvoiceDocumentsForAdmin(context.Context, *connect.Request[invoice.ListInvoiceDocumentsForAdminRequest]) (*connect.Response[invoice.ListInvoiceDocumentsForAdminResponse], error)
	GetInvoiceDocumentForAdmin(context.Context, *connect.Request[invoice.GetInvoiceDocumentForAdminRequest]) (*connect.Response[invoice.GetInvoiceDocumentForAdminResponse], error)
	ResendInvoiceNotificationForAdmin(context.Context, *connect.Request[invoice.ResendInvoiceNotificationForAdminRequest]) (*connect.Response[invoice.ResendInvoiceNotificationResponse], error)
	ListInvoiceJobsForAdmin(context.Context, *connect.Request[invoice.ListInvoiceJobsForAdminRequest]) (*connect.Response[invoice.ListInvoiceJobsForAdminResponse], error)
	GetInvoiceJobForAdmin(context.Context, *connect.Request[invoice.GetInvoiceJobForAdminRequest]) (*connect.Response[invoice.GetInvoiceJobForAdminResponse], error)
	RetryInvoiceJobForAdmin(context.Context, *connect.Request[invoice.RetryInvoiceJobForAdminRequest]) (*connect.Response[invoice.InvoiceJobMutationResponse], error)
	CancelInvoiceJobForAdmin(context.Context, *connect.Request[invoice.CancelInvoiceJobForAdminRequest]) (*connect.Response[invoice.InvoiceJobMutationResponse], error)
	// 端點 73：把停在人工出口、而且**沒有任何 operation** 的文件送回自動線。
	//
	// 🔴 端點 52 以 job_id 為鍵，而自動線落 AWAITING_MANUAL 時 operation 根本不建
	// （§7.1.3 的 AM 節點明文）⇒ 那些文件沒有 job_id，端點 52／53／56 全部組不出請求。
	// 本 RPC 是它們唯一的入口：ResumeFromManual（M1）＋ 補建那件缺席的 ISSUE operation。
	ResumeInvoiceDocumentForAdmin(context.Context, *connect.Request[invoice.ResumeInvoiceDocumentForAdminRequest]) (*connect.Response[invoice.InvoiceJobMutationResponse], error)
	// 受控人工出口（決策 A4：查證 → 雙人確認 → 解鎖 → 回報）
	RequestManualUnlockForAdmin(context.Context, *connect.Request[invoice.RequestManualUnlockForAdminRequest]) (*connect.Response[invoice.ManualUnlockResponse], error)
	ApproveManualUnlockForAdmin(context.Context, *connect.Request[invoice.ApproveManualUnlockForAdminRequest]) (*connect.Response[invoice.ManualUnlockResponse], error)
	ReportManualResultForAdmin(context.Context, *connect.Request[invoice.ReportManualResultForAdminRequest]) (*connect.Response[invoice.InvoiceJobMutationResponse], error)
	// 手動開票（通用 issuer→recipient）
	CreateManualIssuanceForAdmin(context.Context, *connect.Request[invoice.CreateManualIssuanceForAdminRequest]) (*connect.Response[invoice.CreateManualIssuanceForAdminResponse], error)
	// 申訴（A07/A08）與稽核（A10）
	ListInvoiceComplaintsForAdmin(context.Context, *connect.Request[invoice.ListInvoiceComplaintsForAdminRequest]) (*connect.Response[invoice.ListInvoiceComplaintsResponse], error)
	GetInvoiceComplaintForAdmin(context.Context, *connect.Request[invoice.GetInvoiceComplaintForAdminRequest]) (*connect.Response[invoice.InvoiceComplaintResponse], error)
	ActOnInvoiceComplaintForAdmin(context.Context, *connect.Request[invoice.ActOnInvoiceComplaintForAdminRequest]) (*connect.Response[invoice.ActOnInvoiceComplaintForAdminResponse], error)
	ListInvoiceAuditLogsForAdmin(context.Context, *connect.Request[invoice.ListInvoiceAuditLogsForAdminRequest]) (*connect.Response[invoice.ListInvoiceAuditLogsForAdminResponse], error)
	// order-service 在 checkout preview 呼叫：解析該賣家對這一筆訂單的開票模式、
	// 金額拆解、法定告知與待審接單上限。這支決定 B01 能不能讓買家付款。
	ResolveOrderInvoiceModeInternal(context.Context, *connect.Request[invoice.ResolveOrderInvoiceModeInternalRequest]) (*connect.Response[invoice.ResolveOrderInvoiceModeInternalResponse], error)
	// order-service 在 checkout confirm 呼叫：驗證買家發票輸入（載具/統編/捐贈碼格式與
	// 三者互斥）＋ 檢查待審接單上限，回傳可持久化的發票快照。
	ValidateOrderInvoiceInputInternal(context.Context, *connect.Request[invoice.ValidateOrderInvoiceInputInternalRequest]) (*connect.Response[invoice.ValidateOrderInvoiceInputInternalResponse], error)
	// seller 模組與 ADM 查賣家是否已具備開票能力（薄查詢，供其他服務判斷）。
	GetSellerInvoiceCapabilitySimple(context.Context, *connect.Request[invoice.GetSellerInvoiceCapabilitySimpleRequest]) (*connect.Response[invoice.GetSellerInvoiceCapabilitySimpleResponse], error)
	// 單體（platform/bizcalendar，假日資料的擁有者）推送行事曆鏡像：帶入涵蓋區間與區間內的假日，
	// 同一交易內整段覆蓋鏡像與涵蓋區間。任何一個日期不合就整批拒絕、不改鏡像。冪等：同一批重送結果相同。
	// 這支 RPC 與單體的推送隨 A5（invoice 搬進單體）刪除。
	ReplaceBusinessDayMirror(context.Context, *connect.Request[invoice.ReplaceBusinessDayMirrorRequest]) (*connect.Response[invoice.ReplaceBusinessDayMirrorResponse], error)
}

